    async function prepareAppearanceImage(file, t) {
      if (!file || !['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) throw new Error(t('imageType'))
      if (!file.size || file.size > 5 * 1024 * 1024) throw new Error(t('imageSize'))
      const data = await new Promise((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(reader.result)
        reader.onerror = reader.onabort = () => reject(new Error(t('imageRead')))
        reader.readAsDataURL(file)
      })
      const img = await new Promise((resolve, reject) => {
        const picture = new Image()
        picture.onload = () => resolve(picture)
        picture.onerror = () => reject(new Error(t('imageRead')))
        picture.src = data
      })
      if (!img.naturalWidth || !img.naturalHeight || img.naturalWidth > 4096 || img.naturalHeight > 4096) throw new Error(t('imageDimensions'))
      const canvas = document.createElement('canvas')
      const context = canvas.getContext('2d')
      if (!context) throw new Error(t('imageEncode'))
      try {
        for (let edge = 768; edge >= 128; edge = Math.floor(edge * .75)) {
          const scale = Math.min(1, edge / Math.max(img.naturalWidth, img.naturalHeight))
          canvas.width = Math.max(1, Math.round(img.naturalWidth * scale))
          canvas.height = Math.max(1, Math.round(img.naturalHeight * scale))
          context.clearRect(0, 0, canvas.width, canvas.height)
          context.drawImage(img, 0, 0, canvas.width, canvas.height)
          const png = canvas.toDataURL('image/png')
          if (png.startsWith('data:image/png;base64,') && png.length <= 22 + 4 * Math.floor((512 * 1024) / 3)) return png
        }
      } catch { throw new Error(t('imageEncode')) }
      throw new Error(t('imageEncode'))
    }

